package com.brightloop.quotation;
import com.brightloop.catalog.*;import com.brightloop.plan.PlanRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class QuotationTemplateService{
 private final QuotationTemplateRepository templates;private final ProductRepository products;private final ProductVariantRepository variants;private final PlanRepository plans;public QuotationTemplateService(QuotationTemplateRepository t,ProductRepository p,ProductVariantRepository v,PlanRepository pl){templates=t;products=p;variants=v;plans=pl;}
 public record LineRequest(@NotNull Long productId,Long planId,Long variantId,@Min(1) int quantity){}public record Request(@NotBlank @Size(max=140) String name,@Size(max=500) String description,@Min(1) @Max(365) int validityDays,@NotEmpty List<@Valid LineRequest> lines){}public record Line(Long productId,String productName,Long planId,String planName,Long variantId,String variantName,int quantity){}public record Response(Long id,String name,String description,int validityDays,List<Line> lines){static Response of(QuotationTemplate t){return new Response(t.id,t.name,t.description,t.validityDays,t.lines.stream().map(l->new Line(l.getProductId(),l.productName(),l.getPlanId(),l.planName(),l.getVariantId(),l.variantName(),l.quantity)).toList());}}
 @Transactional(readOnly=true) public List<Response> list(){return templates.findAll().stream().map(Response::of).toList();}
 @Transactional public Response create(Request r){if(templates.existsByNameIgnoreCase(r.name()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Template name already exists");var t=new QuotationTemplate(r.name(),r.description(),r.validityDays());for(var line:r.lines())t.addLine(line(t,line));return Response.of(templates.save(t));}
 @Transactional public Response update(Long id,Request r){var t=find(id);if(templates.findAll().stream().anyMatch(x->!x.getId().equals(id)&&x.getName().equalsIgnoreCase(r.name())))throw new ResponseStatusException(HttpStatus.CONFLICT,"Template name already exists");t.name=r.name();t.description=r.description();t.validityDays=r.validityDays();t.lines.clear();for(var line:r.lines())t.addLine(line(t,line));return Response.of(t);}
 @Transactional public void delete(Long id){templates.delete(find(id));}
 public QuotationTemplate find(Long id){return templates.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Quotation template not found"));}
 private QuotationTemplateLine line(QuotationTemplate t,LineRequest r){Product p=products.findById(r.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));var plan=r.planId()==null?null:plans.findById(r.planId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));if(plan!=null&&!plan.getProduct().getId().equals(p.getId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Plan must belong to the selected product");var variant=r.variantId()==null?null:variants.findById(r.variantId()).filter(v->v.getProduct().getId().equals(p.getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variant must belong to the selected product"));return new QuotationTemplateLine(t,p,plan,variant,r.quantity());}
}
